// Finite, JSON-only evidence model. Request values are supplied evidence,
// not outputs generated by this validator or an embedded language model.
export const copy = x => structuredClone(x);
export const key = x => JSON.stringify(canonical(x));
function canonical(x) {
  if (Array.isArray(x)) return x.map(canonical);
  if (x && typeof x === 'object') return Object.fromEntries(Object.keys(x).sort().map(k => [k, canonical(x[k])]));
  return x;
}
export const same = (a, b) => key(a) === key(b);
export const unique = xs => [...new Map(xs.map(x => [key(x), x])).values()];
export const subset = (a, b) => a.every(x => b.some(y => same(x, y)));
export const image = (rows, request) => unique(rows.map(r => r.values[request.coordinate]));
export const quotient = (rows, request) => {
  const groups = new Map();
  for (const r of rows) {
    const k = key(r.values[request.coordinate]);
    if (!groups.has(k)) groups.set(k, []);
    groups.get(k).push(r.id);
  }
  return [...groups.values()];
};
export function sufficientBoundary(rows, request, boundary) {
  return rows.every(a => rows.every(b => !boundary.every(k => same(a.values[k], b.values[k])) || same(a.values[request.coordinate], b.values[request.coordinate])));
}
export function sufficientPartition(rows, request, partition) {
  return partition.every(block => image(rows.filter(r => block.includes(r.id)), request).length === 1);
}
export const refinePartition = (partition, q) => partition.flatMap(block => q.map(group => block.filter(id => group.includes(id))).filter(part => part.length));
function rowsCheck(rows, request, name) {
  if (!Array.isArray(rows) || !rows.length) throw new Error(`${name} must be a nonempty finite array`);
  const ids = new Set();
  for (const row of rows) {
    if (typeof row.id !== 'string' || !row.id || ids.has(row.id)) throw new Error(`${name}: unique nonempty ids required`);
    ids.add(row.id);
    if (typeof row.identity !== 'string' || !row.values || typeof row.values !== 'object' || Array.isArray(row.values)) throw new Error(`${name}: identity and values required`);
    if (!Object.hasOwn(row.values, request.coordinate)) throw new Error(`${name}: missing requested coordinate ${request.coordinate}`);
    if (typeof row.viable !== 'boolean' || !Array.isArray(row.relations) || !Array.isArray(row.provenance)) throw new Error(`${name}: viability, relations and provenance required`);
  }
}
export function prepare(input) {
  // Reject non-JSON data, undefined, NaN and infinity rather than comparing them as null.
  const validateJSON = x => {
    if (x === null || ['string', 'boolean'].includes(typeof x)) return;
    if (typeof x === 'number' && Number.isFinite(x)) return;
    if (Array.isArray(x)) return x.forEach(validateJSON);
    if (x && typeof x === 'object' && Object.getPrototypeOf(x) === Object.prototype) return Object.values(x).forEach(validateJSON);
    throw new Error('Input must contain only finite JSON values');
  };
  validateJSON(input);
  const s = copy(input);
  if (!s.requested_resolution || typeof s.requested_resolution.coordinate !== 'string') throw new Error('requested_resolution.coordinate required');
  if (typeof s.identity !== 'string') throw new Error('identity required');
  s.required_relations ??= [];
  s.provenance ??= [];
  s.prior_evaluations ??= [];
  rowsCheck(s.possibility_space, s.requested_resolution, 'possibility_space');
  if (s.possibility_space.some(r => r.identity !== s.identity || !r.viable || !subset(s.required_relations, r.relations))) throw new Error('Initial possibilities must preserve the declared subject, required relations and viability');
  if (s.candidate_transform) {
    rowsCheck(s.candidate_transform.images, s.requested_resolution, 'candidate_transform.images');
    const ids = new Set(s.possibility_space.map(r => r.id));
    const sources = s.candidate_transform.images.map(r => r.source);
    if (sources.some(id => !ids.has(id)) || new Set(sources).size !== sources.length) throw new Error('Transform images require unique known sources');
  }
  const rows = currentRows(s);
  s.active_boundary ??= unique(rows.flatMap(r => Object.keys(r.values)));
  if (!Array.isArray(s.active_boundary) || s.active_boundary.some(k => rows.some(r => !Object.hasOwn(r.values, k)))) throw new Error('active_boundary must name represented coordinates');
  s.partition ??= [rows.map(r => r.id)];
  const members = s.partition.flat();
  if (!s.partition.every(b => Array.isArray(b) && b.length) || members.length !== rows.length || new Set(members).size !== rows.length || members.some(id => !rows.some(r => r.id === id))) throw new Error('partition must cover every current row exactly once');
  s.discovery_route ??= 'UNSPECIFIED';
  if (!['KNOWLEDGE', 'CAUTIOUS_TRANSFORM', 'QUICK_CANDIDATE', 'UNSPECIFIED'].includes(s.discovery_route)) throw new Error('Unknown discovery route');
  return s;
}
export const currentRows = s => s.candidate_transform?.images ?? s.possibility_space;
export function preservation(s) {
  if (!s.candidate_transform) return {subject: true, relations: true, viability: true, provenance: true};
  const rows = currentRows(s);
  return {
    subject: rows.every(r => r.identity === s.identity),
    relations: rows.every(r => subset(s.required_relations, r.relations)),
    viability: rows.length === s.possibility_space.length && rows.every(r => r.viable),
    provenance: rows.length === s.possibility_space.length && s.possibility_space.every(a => rows.some(b => b.source === a.id && a.provenance.every((event, i) => same(event, b.provenance[i]))))
  };
}
